/* ---- Force-link functions (prevent LTO stripping) ---- */
const void* cutscene_force_link(void);
const void* sprite_force_link(void);
const void* codex_force_link(void);
const void* levels_force_link(void);

/* Call this from main to ensure all content data is linked */
static inline void content_force_link_all(void) {
    volatile const void* p;
    p = cutscene_force_link();
    p = sprite_force_link();
    p = codex_force_link();
    p = levels_force_link();
    (void)p;
}

